      let x_clone = Rc::clone(&x);
      let tails_clone = Rc::clone(&tails);
      let k = bsearch_1(x_clone, tails_clone, v, 0u64, L);
      let tmp_1 = 0u64;
      let p = if eqb(k, tmp_1) {
        0u64
      } else {
        let tmp_2 = sub(k, 1u64);
        rocq_array::get::<u64>(&tails, tmp_2)
