      let tails_ = rocq_array::set::<u64>(tails, k, i);
      let tmp_3 = add(i, 1u64);
      let tmp_4 = if eqb(k, L) {
        add(L, 1u64)
      } else {
        L
      };
      main_loop(x, n, tmp_3, tmp_4, tails_, pred_, ())
    },
    sumbool::right => {
      std::mem::drop(x);
      (L, (tails, pred))
    },
  }
}

